import{WIDTH,HEIGHT,elevationAt}from'./model.js?v=8';
// Match the same triangle diagonal as TerrainPreview's actual indexed mesh.
export function meshElevationAt(field,x,y){const fx=Math.max(0,Math.min(field.nx-1,x/WIDTH*(field.nx-1))),fy=Math.max(0,Math.min(field.ny-1,y/HEIGHT*(field.ny-1))),i=Math.min(field.nx-2,Math.floor(fx)),j=Math.min(field.ny-2,Math.floor(fy)),u=fx-i,v=fy-j,k=j*field.nx+i,a=field.values;return u+v<=1?a[k]*(1-u-v)+a[k+1]*u+a[k+field.nx]*v:a[k+field.nx+1]*(u+v-1)+a[k+1]*(1-v)+a[k+field.nx]*(1-u);}
const lerp=(a,b,t)=>a.map((v,i)=>v+(b[i]-v)*t);
function cutsAtGrid(a,b,field){
 let ts=[0,1];for(const[axis,n,size]of[[0,field.nx,WIDTH],[1,field.ny,HEIGHT]]){const step=size/(n-1),d=b[axis]-a[axis];if(!d)continue;for(let k=Math.floor(Math.min(a[axis],b[axis])/step)+1;k<=Math.floor(Math.max(a[axis],b[axis])/step);k++){const t=(k*step-a[axis])/d;if(t>0&&t<1)ts.push(t);}}
 ts.sort((a,b)=>a-b);ts=ts.filter((t,i)=>!i||t-ts[i-1]>1e-10);const out=[...ts];for(let i=1;i<ts.length;i++){const lo=ts[i-1],hi=ts[i],mid=lerp(a,b,(lo+hi)/2),ix=Math.floor(mid[0]/WIDTH*(field.nx-1)),iy=Math.floor(mid[1]/HEIGHT*(field.ny-1)),c=a[0]/WIDTH*(field.nx-1)+a[1]/HEIGHT*(field.ny-1)-ix-iy-1,d=(b[0]-a[0])/WIDTH*(field.nx-1)+(b[1]-a[1])/HEIGHT*(field.ny-1);if(d){const t=-c/d;if(t>lo+1e-10&&t<hi-1e-10)out.push(t);}}return out.sort((a,b)=>a-b);
}
function nearestPlace(doc,p){let best=null;for(const f of doc.features.filter(f=>f.type==='peak'||f.type==='lake'||f.type==='village'||f.constraint==='saddle')){const q=f.points.reduce((a,p)=>a.map((v,i)=>v+p[i]/f.points.length),[0,0]),d=Math.hypot(q[0]-p[0],q[1]-p[1]);if(!best||d<best.distanceKm)best={id:f.id,name:f.name,distanceKm:d};}return best;}
function summitFindings(doc,field){const found=[],sx=WIDTH/(field.nx-1),sy=HEIGHT/(field.ny-1);for(const f of doc.features.filter(f=>f.type==='peak')){const[x,y]=f.points[0];let highest=null;for(let j=Math.max(1,Math.floor((y-.65)/sy));j<=Math.min(field.ny-2,Math.ceil((y+.65)/sy));j++)for(let i=Math.max(1,Math.floor((x-.65)/sx));i<=Math.min(field.nx-2,Math.ceil((x+.65)/sx));i++){const point=[i*sx,j*sy],d=Math.hypot(point[0]-x,point[1]-y),k=j*field.nx+i,h=field.values[k];if(d<.12||d>.65||h<f.elevation+50)continue;if([k-1,k+1,k-field.nx,k+field.nx,k-field.nx-1,k-field.nx+1,k+field.nx-1,k+field.nx+1].every(n=>field.values[n]<=h)&&(!highest||h>highest.surface))highest={id:f.id,name:f.name,point,peakPoint:[x,y],elevation:f.elevation,surface:h,heightAboveLabel:h-f.elevation,distanceKm:d};}if(highest)found.push(highest);}return found;}
export function auditTerrain(doc,field,{threshold=50}={}){
 const contours=[],sections=[];let totalKm=0,overKm=0,maxError=0,weightedError=0;
 for(const f of doc.features.filter(f=>f.type==='contour')){
  let maximum=null,lengthKm=0,errorIntegral=0,overLengthKm=0;
  for(let s=0;s<f.points.length-(f.closed?0:1);s++){const a=f.points[s],b=f.points[(s+1)%f.points.length],length=Math.hypot(b[0]-a[0],b[1]-a[1]),ts=cutsAtGrid(a,b,field);for(let n=1;n<ts.length;n++){
    const p=lerp(a,b,ts[n-1]),q=lerp(a,b,ts[n]),h0=meshElevationAt(field,...p),h1=meshElevationAt(field,...q),e0=h0-f.elevation,e1=h1-f.elevation,len=length*(ts[n]-ts[n-1]);for(const[point,h,error]of[[p,h0,e0],[q,h1,e1]])if(!maximum||Math.abs(error)>maximum.error)maximum={point,height:h,error:Math.abs(error),signedError:error};lengthKm+=len;
    const breaks=[0,1];if(e0*e1<0)breaks.push(-e0/(e1-e0));for(const level of[-threshold,threshold]){const t=(level-e0)/(e1-e0);if(t>0&&t<1)breaks.push(t);}breaks.sort((a,b)=>a-b);for(let z=1;z<breaks.length;z++){const lo=breaks[z-1],hi=breaks[z],ea=e0+(e1-e0)*lo,eb=e0+(e1-e0)*hi,part=len*(hi-lo);errorIntegral+=(Math.abs(ea)+Math.abs(eb))/2*part;if(Math.abs((ea+eb)/2)>threshold){overLengthKm+=part;const start=lerp(p,q,lo),end=lerp(p,q,hi),point=Math.abs(ea)>Math.abs(eb)?start:end;sections.push({contourId:f.id,elevation:f.elevation,start,end,point,error:Math.max(Math.abs(ea),Math.abs(eb)),lengthKm:part});}}
   }}
  contours.push({id:f.id,name:f.name,elevation:f.elevation,lengthKm,meanError:lengthKm?errorIntegral/lengthKm:0,overLengthKm,...maximum});totalKm+=lengthKm;overKm+=overLengthKm;weightedError+=errorIntegral;maxError=Math.max(maxError,maximum?.error||0);
 }
 const cells=new Map(),parent=sections.map((_,i)=>i),find=i=>parent[i]===i?i:parent[i]=find(parent[i]);for(let i=0;i<sections.length;i++){const p=sections[i].point,gx=Math.floor(p[0]/.3),gy=Math.floor(p[1]/.3);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)for(const j of cells.get(`${gx+dx},${gy+dy}`)||[]){const q=sections[j].point;if(Math.hypot(p[0]-q[0],p[1]-q[1])<=.3)parent[find(i)]=find(j);}const key=`${gx},${gy}`;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(i);}
 const grouped=new Map();sections.forEach((s,i)=>{const k=find(i);if(!grouped.has(k))grouped.set(k,[]);grouped.get(k).push(s);});
 const regions=[...grouped.values()].map(ss=>{const worst=ss.reduce((a,b)=>a.error>b.error?a:b),bilinearSurface=elevationAt(field,...worst.point),bounds={west:Infinity,east:-Infinity,north:Infinity,south:-Infinity};for(const s of ss)for(const p of[s.start,s.end]){bounds.west=Math.min(bounds.west,p[0]);bounds.east=Math.max(bounds.east,p[0]);bounds.north=Math.min(bounds.north,p[1]);bounds.south=Math.max(bounds.south,p[1]);}return{point:worst.point,maxError:worst.error,elevation:worst.elevation,surface:meshElevationAt(field,...worst.point),bilinearSurface,bilinearError:Math.abs(bilinearSurface-worst.elevation),lengthKm:ss.reduce((sum,s)=>sum+s.lengthKm,0),contourIds:[...new Set(ss.map(s=>s.contourId))],place:nearestPlace(doc,worst.point),bounds};}).sort((a,b)=>b.maxError-a.maxError);
 return{schema:'snowvalley-terrain-audit/1',title:doc.title,revision:doc.revision,appliedRepairs:doc.summitRepair||null,generatedAt:new Date().toISOString(),thresholdMetres:threshold,gridSpacingMetres:WIDTH/(field.nx-1)*1000,method:'Exact contour intersections with rendered triangle edges; 50 m is a design review filter, not a surveying standard.',summary:{contourCount:contours.length,totalKm,overKm,maxError,meanError:weightedError/(totalKm||1),regions:regions.length},regions,summitFindings:summitFindings(doc,field),contours:contours.sort((a,b)=>b.error-a.error)};
}
